CREATE OR REPLACE FUNCTION public.lts_v246_invalidate_finance_cache()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE changed boolean:=false; ignored text[]:=ARRAY[]::text[];
BEGIN
 IF TG_TABLE_SCHEMA='public' AND left(TG_TABLE_NAME,7)='health_' THEN RETURN NULL; END IF;
 IF TG_OP='TRUNCATE' THEN changed:=true;
 ELSIF TG_TABLE_NAME='lts_open_finance_observation' THEN
  IF TG_OP='INSERT' THEN
   SELECT EXISTS(SELECT 1 FROM new_rows n
    WHERE n.resource_type='balance' AND n.normalized_payload->>'account_type'='CHECKING_ACCOUNT'
    AND NOT EXISTS(SELECT 1 FROM public.lts_open_finance_observation o
      WHERE o.user_id=n.user_id AND o.connection_id=n.connection_id AND o.resource_type='balance'
       AND o.normalized_payload->>'account_type'='CHECKING_ACCOUNT'
       AND o.provider_record_id=n.provider_record_id AND o.raw_hash=n.raw_hash
       AND o.normalized_payload=n.normalized_payload AND o.raw_payload=n.raw_payload
       AND NOT EXISTS(SELECT 1 FROM new_rows inserted WHERE inserted.id=o.id))) INTO changed;
  ELSIF TG_OP='DELETE' THEN
   SELECT EXISTS(SELECT 1 FROM old_rows WHERE resource_type='balance' AND normalized_payload->>'account_type'='CHECKING_ACCOUNT') INTO changed;
  ELSE
   SELECT EXISTS(
    (SELECT to_jsonb(n)-ARRAY['sync_run_id','observed_at','ingest_action','reconciliation'] FROM new_rows n
      WHERE resource_type='balance' AND normalized_payload->>'account_type'='CHECKING_ACCOUNT'
     EXCEPT ALL
     SELECT to_jsonb(o)-ARRAY['sync_run_id','observed_at','ingest_action','reconciliation'] FROM old_rows o
      WHERE resource_type='balance' AND normalized_payload->>'account_type'='CHECKING_ACCOUNT')
    UNION ALL
    (SELECT to_jsonb(o)-ARRAY['sync_run_id','observed_at','ingest_action','reconciliation'] FROM old_rows o
      WHERE resource_type='balance' AND normalized_payload->>'account_type'='CHECKING_ACCOUNT'
     EXCEPT ALL
     SELECT to_jsonb(n)-ARRAY['sync_run_id','observed_at','ingest_action','reconciliation'] FROM new_rows n
      WHERE resource_type='balance' AND normalized_payload->>'account_type'='CHECKING_ACCOUNT')) INTO changed;
  END IF;
 ELSIF TG_OP='INSERT' THEN SELECT EXISTS(SELECT 1 FROM new_rows) INTO changed;
 ELSIF TG_OP='DELETE' THEN SELECT EXISTS(SELECT 1 FROM old_rows) INTO changed;
 ELSE
  IF TG_TABLE_NAME='lts_open_finance_staging' THEN ignored:=ARRAY['sync_run_id','last_seen_at','updated_at'];
  ELSIF TG_TABLE_NAME='lts_open_finance_connection' THEN ignored:=ARRAY['last_attempt_at','last_success_at','last_error_code','last_error_summary','updated_at']; END IF;
  SELECT EXISTS(
   (SELECT to_jsonb(n)-ignored FROM new_rows n EXCEPT ALL SELECT to_jsonb(o)-ignored FROM old_rows o)
   UNION ALL
   (SELECT to_jsonb(o)-ignored FROM old_rows o EXCEPT ALL SELECT to_jsonb(n)-ignored FROM new_rows n)) INTO changed;
 END IF;
 IF changed THEN
  UPDATE public.lts_read_cache_epoch_v242 SET epoch=epoch+1 WHERE singleton=true;
  DELETE FROM public.lts_v229_read_cache WHERE user_id IS NOT NULL;
 END IF;
 RETURN NULL;
END $function$
;
CREATE TRIGGER fixture_evidence_insert AFTER INSERT ON public.lts_reconciliation_evidence REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION public.lts_v246_invalidate_finance_cache();
CREATE TRIGGER fixture_evidence_update AFTER UPDATE ON public.lts_reconciliation_evidence REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION public.lts_v246_invalidate_finance_cache();
CREATE TRIGGER fixture_evidence_delete AFTER DELETE ON public.lts_reconciliation_evidence REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION public.lts_v246_invalidate_finance_cache();
CREATE TRIGGER fixture_decision_insert AFTER INSERT ON public.lts_v178_review_decision REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION public.lts_v246_invalidate_finance_cache();
CREATE TRIGGER fixture_decision_delete AFTER DELETE ON public.lts_v178_review_decision REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION public.lts_v246_invalidate_finance_cache();
CREATE TRIGGER fixture_decision_update AFTER UPDATE ON public.lts_v178_review_decision REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION public.lts_v246_invalidate_finance_cache();
CREATE FUNCTION public.fixture_atomic_fcontract(sig text) RETURNS jsonb LANGUAGE sql SET search_path TO pg_catalog,public AS $cf$
 SELECT jsonb_build_object('signature',item->>'signature','definition_md5',md5(pg_get_functiondef(p.oid)),
 'prosrc_sha256',encode(sha256(convert_to(p.prosrc,'UTF8')),'hex'),'owner',pg_get_userbyid(p.proowner),
 'acl',p.proacl::text[],'config',p.proconfig,'language',la.lanname,'volatility',p.provolatile,
 'security_definer',p.prosecdef,'result',pg_get_function_result(p.oid)) FROM pg_proc p JOIN pg_language la ON la.oid=p.prolang CROSS JOIN (SELECT jsonb_build_object('signature',sig) item)q WHERE p.oid=to_regprocedure(sig)
$cf$;
CREATE FUNCTION public.fixture_atomic_rcontract(n text) RETURNS jsonb LANGUAGE sql SET search_path TO pg_catalog,public AS $cr$
 SELECT jsonb_build_object('name',r.relname,'owner',pg_get_userbyid(r.relowner),'kind',r.relkind,
 'acl',r.relacl::text[],'rls',r.relrowsecurity,'force_rls',r.relforcerowsecurity,
 'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),
  'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'acl',a.attacl::text[],
  'default',pg_get_expr(ad.adbin,ad.adrelid)) ORDER BY a.attnum)
  FROM pg_attribute a LEFT JOIN pg_attrdef ad ON ad.adrelid=a.attrelid AND ad.adnum=a.attnum WHERE a.attrelid=r.oid AND a.attnum>0 AND NOT a.attisdropped),
 'policies',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',p.polname,'command',p.polcmd,'roles',p.polroles,
  'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid),'permissive',p.polpermissive) ORDER BY p.polname),'[]') FROM pg_policy p WHERE p.polrelid=r.oid),
 'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',c.conname,'type',c.contype,'definition',pg_get_constraintdef(c.oid),'validated',c.convalidated) ORDER BY c.conname),'[]') FROM pg_constraint c WHERE c.conrelid=r.oid),
 'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_object('definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready,'unique',i.indisunique) ORDER BY i.indexrelid::regclass::text),'[]') FROM pg_index i WHERE i.indrelid=r.oid),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid),'function_md5',md5(pg_get_functiondef(t.tgfoid))) ORDER BY t.tgname),'[]') FROM pg_trigger t WHERE t.tgrelid=r.oid AND NOT t.tgisinternal)) FROM pg_class r WHERE r.oid=to_regclass('public.'||n)
$cr$;
INSERT INTO public.fixture_atomic_config SELECT 'required',jsonb_build_object('functions',(SELECT jsonb_agg(('public.'||p.oid::regprocedure::text)::text ORDER BY ('public.'||p.oid::regprocedure::text)::text) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'lts_%'),'relations','["financial_events","lts_access_audit","lts_open_finance_staging","lts_read_cache_epoch_v242","lts_reconciliation_evidence","lts_v178_review_decision","lts_v229_read_cache"]'::jsonb);
-- regprocedure emits unqualified names under the pinned search_path. Qualify once, explicitly.
UPDATE public.fixture_atomic_config SET value=jsonb_set(value,'{functions}',(SELECT jsonb_agg(to_jsonb(replace(x,'public.public.','public.')) ORDER BY replace(x,'public.public.','public.')) FROM jsonb_array_elements_text(value->'functions')x)) WHERE key='required';
CREATE FUNCTION public.fixture_atomic_catalog() RETURNS jsonb LANGUAGE sql AS $cat$
 SELECT jsonb_build_object('functions',(SELECT jsonb_agg(public.fixture_atomic_fcontract(x) ORDER BY x) FROM public.fixture_atomic_config c CROSS JOIN LATERAL jsonb_array_elements_text(c.value->'functions')x WHERE c.key='required'),
 'relations',(SELECT jsonb_agg(public.fixture_atomic_rcontract(x) ORDER BY x) FROM public.fixture_atomic_config c CROSS JOIN LATERAL jsonb_array_elements_text(c.value->'relations')x WHERE c.key='required'))
$cat$;
CREATE TABLE public.fixture_atomic_bodies(kind text,signature text,definition text,contract jsonb,PRIMARY KEY(kind,signature));
DO $compile$ DECLARE k text;r record;sig text;d text;BEGIN
 FOREACH k IN ARRAY ARRAY['original','candidate'] LOOP
  PERFORM public.fixture_install(k);
  FOR r IN SELECT name,ddl FROM public.fixture_templates WHERE name LIKE '%_'||k LOOP
   sig:=CASE WHEN r.name LIKE 'expense%' THEN 'public.lts_v229_expense_rows(uuid,date,date)' ELSE 'public.lts_browser_card_detail_v226(text,date)' END;
   d:=replace(r.ddl,'UNBOUND_CANONICAL_SHA256_REQUIRES_PG17_REVIEW',(SELECT value#>>'{}' FROM public.fixture_control WHERE key='pin'));
   INSERT INTO public.fixture_atomic_bodies VALUES(k,sig,d,public.fixture_atomic_fcontract(sig));
  END LOOP;
 END LOOP;
 PERFORM public.fixture_install('original');
END $compile$;
CREATE TABLE public.fixture_atomic_templates(kind text PRIMARY KEY,ddl text);
