CREATE FUNCTION public.fixture_atomic_reset() RETURNS void LANGUAGE plpgsql AS $reset_atomic$ BEGIN
 PERFORM public.fixture_install('original');
 REVOKE ALL ON FUNCTION public.lts_v229_expense_rows(uuid,date,date) FROM PUBLIC,authenticated,anon,service_role;
 GRANT EXECUTE ON FUNCTION public.lts_v229_expense_rows(uuid,date,date) TO service_role;
 REVOKE ALL ON FUNCTION public.lts_browser_card_detail_v226(text,date) FROM PUBLIC,authenticated,anon,service_role;
 GRANT EXECUTE ON FUNCTION public.lts_browser_card_detail_v226(text,date) TO authenticated,service_role;
 ALTER TABLE public.lts_reconciliation_evidence ENABLE ROW LEVEL SECURITY;
 TRUNCATE public.lts_open_finance_staging,public.lts_reconciliation_evidence,public.lts_v178_review_decision,public.lts_access_audit,public.financial_events,public.lts_v229_read_cache;
 INSERT INTO public.lts_open_finance_staging SELECT * FROM jsonb_populate_recordset(NULL::public.lts_open_finance_staging,(SELECT payload FROM public.fixture_atomic_saved WHERE name='sources'));
 INSERT INTO public.lts_v178_review_decision SELECT * FROM jsonb_populate_recordset(NULL::public.lts_v178_review_decision,(SELECT payload FROM public.fixture_atomic_saved WHERE name='decisions'));
 INSERT INTO public.lts_v229_read_cache VALUES('11111111-1111-4111-8111-111111111111','owner','{}'),('11111111-1111-4111-8111-222222222222','other-owner','{}'),(null,'null-user-sentinel','{}');
 UPDATE public.lts_read_cache_epoch_v242 SET epoch=100 WHERE singleton;
 PERFORM set_config('fixture.uid','11111111-1111-4111-8111-111111111111',true);
 PERFORM set_config('fixture.email','owner@example.invalid',true);
END $reset_atomic$;
CREATE FUNCTION public.fixture_atomic_lease(kind text) RETURNS jsonb LANGUAGE plpgsql AS $lease_atomic$
DECLARE l jsonb;e jsonb;d jsonb;a jsonb;c jsonb;fs jsonb;ep bigint;
BEGIN
 SELECT epoch INTO ep FROM public.lts_read_cache_epoch_v242 WHERE singleton;
 SELECT jsonb_agg(to_jsonb(s) ORDER BY s.id) INTO fs FROM public.lts_open_finance_staging s WHERE s.user_id='11111111-1111-4111-8111-111111111111' AND s.id IN('22222222-2222-4222-8222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444');
 SELECT to_jsonb(x) INTO d FROM public.lts_v178_review_decision x WHERE source_ref='33333333-3333-4333-8333-333333333333';
 l:=jsonb_build_object('ready',true,'database',current_database(),'role',current_user,'owner_id','11111111-1111-4111-8111-111111111111','expires_at',clock_timestamp()+interval '5 minutes','current_epoch',ep,'source_full_beforeimages',fs,'prior_decision',d,'catalog_contracts',public.fixture_atomic_catalog());
 IF kind='apply' THEN
  SELECT value INTO e FROM public.fixture_atomic_config WHERE key='evidence_insert';
  l:=l||jsonb_build_object('operation_id','55555555-5555-4555-8555-555555555555','immutable_fingerprint',e#>>'{metadata,immutable_fingerprint}','evidence_insert',e,
  'representative_decision_insert',d||jsonb_build_object('source_ref','22222222-2222-4222-8222-222222222222','decision_basis','owner_confirmed_nominal_composite_identity:55555555-5555-4555-8555-555555555555','decided_at','2020-10-16T00:00:00+00:00'),
  'required_gates','{"competing_writer_gate_passed":true,"consumer_pg339_passed":true,"fresh_financial_and_catalog_leases":true,"independent_review_passed":true,"policy_scope_released":true,"transactional_pg_passed":true}'::jsonb,
  'consumer_replacements',(SELECT jsonb_agg(jsonb_build_object('signature',n.signature,'definition',n.definition,'reviewed_definition_sha256',encode(sha256(convert_to(n.definition,'UTF8')),'hex'),'before_contract',o.contract,'after_contract',n.contract) ORDER BY n.signature) FROM public.fixture_atomic_bodies n JOIN public.fixture_atomic_bodies o USING(signature) WHERE n.kind='candidate' AND o.kind='original'));
 ELSE
  SELECT to_jsonb(x) INTO a FROM public.lts_access_audit x WHERE action='option_a_nominal_apply_v1';
  SELECT to_jsonb(x) INTO e FROM public.lts_reconciliation_evidence x WHERE id='55555555-5555-4555-8555-555555555555';
  SELECT to_jsonb(x) INTO d FROM public.lts_v178_review_decision x WHERE source_ref='22222222-2222-4222-8222-222222222222';
  l:=l||jsonb_build_object('apply_operation_id','55555555-5555-4555-8555-555555555555','rollback_operation_id','99999999-9999-4999-8999-999999999999','apply_audit_id',a->'id','apply_receipt_current_sha256',encode(sha256(convert_to(a::text,'UTF8')),'hex'),'current_evidence_image',e,'current_representative_decision',d,
  'expected_revoked_evidence',jsonb_set(e,'{metadata,state}',jsonb_build_object('active',false,'revoked_at','2020-10-17T00:00:00+00:00','revocation_operation_id','99999999-9999-4999-8999-999999999999')),
  'required_gates','{"coordinator_compensation_decision":true,"fresh_rollback_leases":true,"independent_policy_review":true,"transactional_pg_passed":true}'::jsonb,
  'restore_original_definitions',(SELECT jsonb_agg(jsonb_build_object('signature',n.signature,'definition',o.definition,'reviewed_definition_sha256',encode(sha256(convert_to(o.definition,'UTF8')),'hex'),'before_contract',n.contract,'after_contract',o.contract) ORDER BY n.signature) FROM public.fixture_atomic_bodies n JOIN public.fixture_atomic_bodies o USING(signature) WHERE n.kind='candidate' AND o.kind='original'));
 END IF;
 RETURN l;
END $lease_atomic$;
CREATE FUNCTION public.fixture_atomic_complete_lease(kind text) RETURNS jsonb LANGUAGE plpgsql AS $complete_atomic$
DECLARE l jsonb;s jsonb;a jsonb;c jsonb;BEGIN
 l:=public.fixture_atomic_lease(kind);
 SELECT to_jsonb(x) INTO a FROM public.lts_access_audit x WHERE action='option_a_nominal_apply_v1';
 SELECT to_jsonb(x) INTO c FROM public.lts_access_audit x WHERE action='option_a_nominal_rollback_v1';
 s:=jsonb_build_object('evidence_rows',(SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM public.lts_reconciliation_evidence x),'decision',(SELECT to_jsonb(x) FROM public.lts_v178_review_decision x WHERE source_ref='22222222-2222-4222-8222-222222222222'),'receipts',(SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM public.lts_access_audit x),'function_contracts',(SELECT jsonb_agg(public.fixture_atomic_fcontract(signature) ORDER BY signature) FROM public.fixture_atomic_bodies WHERE kind='original'),'receipt_sha256',encode(sha256(convert_to(a::text,'UTF8')),'hex'),'apply_receipt_sha256',encode(sha256(convert_to(a::text,'UTF8')),'hex'),'compensation_receipt_sha256',encode(sha256(convert_to(c::text,'UTF8')),'hex'));
 RETURN l||jsonb_build_object(CASE WHEN kind='apply' THEN 'expected_complete_state' ELSE 'expected_compensated_state' END,s);
END $complete_atomic$;
CREATE FUNCTION public.fixture_atomic_sql(kind text,l jsonb,inject_final boolean DEFAULT false) RETURNS text LANGUAGE plpgsql AS $sql_atomic$ DECLARE d text;BEGIN
 SELECT ddl INTO STRICT d FROM public.fixture_atomic_templates t WHERE t.kind=$1;
 d:=replace(d,'__ATOMIC_LEASE__',quote_literal(l::text)||'::jsonb');
 IF inject_final THEN d:=replace(d,'END $option_a_'||kind||'$;',E'RAISE EXCEPTION ''fixture final failure'';\nEND $option_a_'||kind||'$;'); END IF;
 RETURN d;
END $sql_atomic$;
CREATE FUNCTION public.fixture_atomic_snapshot() RETURNS jsonb LANGUAGE plpgsql AS $snap_atomic$
DECLARE x text;v jsonb;r jsonb:='{}';BEGIN
 FOREACH x IN ARRAY ARRAY['lts_open_finance_staging','lts_reconciliation_evidence','lts_v178_review_decision','financial_events','lts_access_audit','lts_read_cache_epoch_v242','lts_v229_read_cache','fixture_expenses','fixture_card_rows','fixture_control'] LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),''[]''::jsonb) FROM public.%I t',x) INTO v;r:=r||jsonb_build_object(x,v);
 END LOOP;
 RETURN r||jsonb_build_object('catalog',public.fixture_atomic_catalog());
END $snap_atomic$;
CREATE FUNCTION public.fixture_atomic_exec(kind text,l jsonb) RETURNS void LANGUAGE plpgsql AS $exec_atomic$ BEGIN EXECUTE public.fixture_atomic_sql(kind,l); END $exec_atomic$;
CREATE FUNCTION public.fixture_atomic_expect_fail(kind text,l jsonb,label text,pattern text DEFAULT '.',inject_final boolean DEFAULT false) RETURNS void LANGUAGE plpgsql AS $fail_atomic$
DECLARE before_image jsonb;err text;BEGIN
 before_image:=public.fixture_atomic_snapshot();
 BEGIN EXECUTE public.fixture_atomic_sql(kind,l,inject_final); EXCEPTION WHEN OTHERS THEN err:=SQLERRM; END;
 PERFORM public.fixture_assert(err IS NOT NULL AND err~pattern,label||'/rejected');
 PERFORM public.fixture_assert(public.fixture_atomic_snapshot()=before_image,label||'/atomic unchanged');
END $fail_atomic$;
CREATE FUNCTION public.fixture_atomic_competitor() RETURNS void LANGUAGE sql AS $competitor_atomic$
 INSERT INTO public.lts_reconciliation_evidence SELECT * FROM jsonb_populate_record(NULL::public.lts_reconciliation_evidence,
 (SELECT value||jsonb_build_object('id','66666666-6666-4666-8666-666666666666','source_ref','fixture-conflicting-contract') FROM public.fixture_atomic_config WHERE key='evidence_insert'))
$competitor_atomic$;
SELECT public.fixture_atomic_reset();
